(function(){
"use strict";
// Generated in the user's code style; assembled by Lab.tsScript in ts-core.js.
Lab.ts({
"bz-quad":{"k":"S","what":"A quadratic Bézier drawn with dots. The control point bobs up and down, and an orange ball rides the curve.","services":[],"variables":"","functions":"local function QuadBezier(p0, p1, p2, t)\n\treturn p0:Lerp(p1, t):Lerp(p1:Lerp(p2, t), t)\nend\n\nlocal function CubicBezier(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn p0 * oneMinusT ^ 3 + p1 * (3 * oneMinusT ^ 2 * t) + p2 * (3 * oneMinusT * t ^ 2) + p3 * t ^ 3\nend\n\nlocal function CubicTangent(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn (p1 - p0) * (3 * oneMinusT ^ 2) + (p2 - p1) * (6 * oneMinusT * t) + (p3 - p2) * (3 * t ^ 2)\nend","setup":"local p0, p2 = ORIGIN + Vector3.new(-12, 1, 0), ORIGIN + Vector3.new(12, 1, 0)\nlocal control = MakePart(Vector3.new(1, 1, 1), ORIGIN, Color3.fromRGB(163, 162, 165), { CanCollide = false })\nlocal dots = {}\n\nfor i = 0, 30 do\n\tdots[i] = MakePart(\n\t\tVector3.new(0.4, 0.4, 0.4),\n\t\tORIGIN,\n\t\tColor3.fromRGB(18, 147, 154),\n\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t)\nend\n\nlocal rider = MakePart(\n\tVector3.new(1.4, 1.4, 1.4),\n\tp0,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false, Material = Enum.Material.Neon }\n)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal p1 = ORIGIN + Vector3.new(math.sin(now * 0.5) * 6, 8 + math.sin(now) * 4, -4)\n\tcontrol.Position = p1\n\tfor i, dot in dots do\n\t\tdot.Position = QuadBezier(p0, p1, p2, i / 30)\n\tend\n\trider.Position = QuadBezier(p0, p1, p2, 0.5 - 0.5 * math.cos(now * 1.2))\nend)"},
"bz-cubic":{"k":"S","what":"A cubic Bézier S-curve with two control points, drawn with dots, with a ball riding along it.","services":[],"variables":"","functions":"local function QuadBezier(p0, p1, p2, t)\n\treturn p0:Lerp(p1, t):Lerp(p1:Lerp(p2, t), t)\nend\n\nlocal function CubicBezier(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn p0 * oneMinusT ^ 3 + p1 * (3 * oneMinusT ^ 2 * t) + p2 * (3 * oneMinusT * t ^ 2) + p3 * t ^ 3\nend\n\nlocal function CubicTangent(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn (p1 - p0) * (3 * oneMinusT ^ 2) + (p2 - p1) * (6 * oneMinusT * t) + (p3 - p2) * (3 * t ^ 2)\nend","setup":"local p0, p3 = ORIGIN + Vector3.new(-14, 1, 0), ORIGIN + Vector3.new(14, 1, 0)\nlocal handle1 = MakePart(Vector3.new(1, 1, 1), ORIGIN, Color3.fromRGB(163, 162, 165), { CanCollide = false })\nlocal handle2 = MakePart(Vector3.new(1, 1, 1), ORIGIN, Color3.fromRGB(163, 162, 165), { CanCollide = false })\nlocal dots = {}\n\nfor i = 0, 40 do\n\tdots[i] = MakePart(\n\t\tVector3.new(0.4, 0.4, 0.4),\n\t\tORIGIN,\n\t\tColor3.fromRGB(18, 147, 154),\n\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t)\nend\n\nlocal rider = MakePart(\n\tVector3.new(1.4, 1.4, 1.4),\n\tp0,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false, Material = Enum.Material.Neon }\n)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal p1 = ORIGIN + Vector3.new(-6, 10 + math.sin(now) * 3, -6)\n\tlocal p2 = ORIGIN + Vector3.new(6, 1 + math.cos(now) * 2, 8)\n\thandle1.Position, handle2.Position = p1, p2\n\tfor i, dot in dots do\n\t\tdot.Position = CubicBezier(p0, p1, p2, p3, i / 40)\n\tend\n\trider.Position = CubicBezier(p0, p1, p2, p3, 0.5 - 0.5 * math.cos(now))\nend)"},
"bz-follow":{"k":"S","what":"A cart travels a cubic track at a constant speed (using a distance table) and always faces along the curve (tangent).","services":[],"variables":"local _speed = 12","functions":"local function QuadBezier(p0, p1, p2, t)\n\treturn p0:Lerp(p1, t):Lerp(p1:Lerp(p2, t), t)\nend\n\nlocal function CubicBezier(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn p0 * oneMinusT ^ 3 + p1 * (3 * oneMinusT ^ 2 * t) + p2 * (3 * oneMinusT * t ^ 2) + p3 * t ^ 3\nend\n\nlocal function CubicTangent(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn (p1 - p0) * (3 * oneMinusT ^ 2) + (p2 - p1) * (6 * oneMinusT * t) + (p3 - p2) * (3 * t ^ 2)\nend","setup":"local p0, p1, p2, p3 =\n\tORIGIN + Vector3.new(-16, 1, 8),\n\tORIGIN + Vector3.new(-16, 1, -14),\n\tORIGIN + Vector3.new(16, 6, 14),\n\tORIGIN + Vector3.new(16, 1, -8)\n\nlocal SAMPLES, lengths, total = 200, { 0 }, 0\nlocal previousPoint = p0\n\nfor i = 1, SAMPLES do\n\tlocal point = CubicBezier(p0, p1, p2, p3, i / SAMPLES)\n\ttotal += (point - previousPoint).Magnitude\n\tlengths[i + 1] = total\n\tpreviousPoint = point\n\tif i % 5 == 0 then\n\t\tMakePart(Vector3.new(0.3, 0.3, 0.3), point, Color3.fromRGB(90, 90, 100), { CanCollide = false })\n\tend\nend\n\nlocal function TAtDistance(distance)\n\tfor i = 2, #lengths do\n\t\tif lengths[i] >= distance then\n\t\t\tlocal lengthBefore, lengthAfter = lengths[i - 1], lengths[i]\n\t\t\treturn (i - 2 + (distance - lengthBefore) / (lengthAfter - lengthBefore)) / SAMPLES\n\t\tend\n\tend\n\treturn 1\nend\n\nlocal cart = MakePart(Vector3.new(2, 1.2, 3), p0, Color3.fromRGB(226, 133, 26), { CanCollide = false })","runtime":"runService.Heartbeat:Connect(function()\n\tlocal t = TAtDistance((os.clock() * _speed) % total)\n\tlocal position = CubicBezier(p0, p1, p2, p3, t) + Vector3.new(0, 0.8, 0)\n\tcart.CFrame = CFrame.lookAt(position, position + CubicTangent(p0, p1, p2, p3, t))\nend)"},
"bz-throw":{"k":"S","what":"Every 2 seconds a ball is lobbed at the nearest player (or a random spot) along a quadratic arc and lands exactly there.","services":[],"variables":"","functions":"local function QuadBezier(p0, p1, p2, t)\n\treturn p0:Lerp(p1, t):Lerp(p1:Lerp(p2, t), t)\nend\n\nlocal function CubicBezier(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn p0 * oneMinusT ^ 3 + p1 * (3 * oneMinusT ^ 2 * t) + p2 * (3 * oneMinusT * t ^ 2) + p3 * t ^ 3\nend\n\nlocal function CubicTangent(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn (p1 - p0) * (3 * oneMinusT ^ 2) + (p2 - p1) * (6 * oneMinusT * t) + (p3 - p2) * (3 * t ^ 2)\nend","setup":"local launcher = MakePart(Vector3.new(3, 3, 3), ORIGIN + Vector3.new(-18, 1.5, 0), Color3.fromRGB(60, 60, 70))\nlocal random = Random.new()","runtime":"while true do\n\tlocal root = GetNearestRoot(launcher.Position, 60)\n\tlocal target = root and root.Position - Vector3.new(0, 2.5, 0)\n\t\tor ORIGIN + Vector3.new(random:NextNumber(-5, 15), 0.5, random:NextNumber(-10, 10))\n\tlocal p0 = launcher.Position + Vector3.new(0, 2, 0)\n\tlocal p1 = (p0 + target) / 2 + Vector3.new(0, 18, 0)\n\tlocal ball = MakePart(\n\t\tVector3.new(1.4, 1.4, 1.4),\n\t\tp0,\n\t\tColor3.fromRGB(226, 133, 26),\n\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t)\n\tlocal start = os.clock()\n\twhile os.clock() - start < 1.3 do\n\t\tball.Position = QuadBezier(p0, p1, target, (os.clock() - start) / 1.3)\n\t\trunService.Heartbeat:Wait()\n\tend\n\tlocal explosion = Instance.new(\"Explosion\")\n\texplosion.Position = target\n\texplosion.BlastPressure = 0\n\texplosion.DestroyJointRadiusPercent = 0\n\texplosion.Parent = workspace\n\tball:Destroy()\n\ttask.wait(2)\nend"},
"bz-catmull":{"k":"S","what":"A drone patrols a closed loop through six waypoints using a Catmull-Rom spline, which passes through every point.","services":[],"variables":"","functions":"local function CatmullRom(p0, p1, p2, p3, t)\n\treturn 0.5\n\t\t* (\n\t\t\t(2 * p1)\n\t\t\t+ (p2 - p0) * t\n\t\t\t+ (2 * p0 - 5 * p1 + 4 * p2 - p3) * t ^ 2\n\t\t\t+ (3 * p1 - p0 - 3 * p2 + p3) * t ^ 3\n\t\t)\nend","setup":"local waypoints = {}\n\nfor i = 1, 6 do\n\tlocal angle = (i - 1) / 6 * math.pi * 2\n\twaypoints[i] = ORIGIN\n\t\t+ Vector3.new(\n\t\t\tmath.cos(angle) * (10 + (i % 2) * 5),\n\t\t\t3 + (i % 3) * 2,\n\t\t\tmath.sin(angle) * (10 + (i % 2) * 5)\n\t\t)\n\tMakePart(Vector3.new(1, 1, 1), waypoints[i], Color3.fromRGB(18, 147, 154), { CanCollide = false })\nend\n\nlocal function WaypointAt(i)\n\treturn waypoints[(i - 1) % #waypoints + 1]\nend\n\nlocal drone =\n\tMakePart(Vector3.new(1.5, 1, 2.5), waypoints[1], Color3.fromRGB(226, 133, 26), { CanCollide = false })","runtime":"runService.Heartbeat:Connect(function()\n\tlocal progress = (os.clock() * 0.6) % #waypoints\n\tlocal i, t = math.floor(progress) + 1, progress % 1\n\tlocal position = CatmullRom(WaypointAt(i - 1), WaypointAt(i), WaypointAt(i + 1), WaypointAt(i + 2), t)\n\tlocal ahead = CatmullRom(\n\t\tWaypointAt(i - 1),\n\t\tWaypointAt(i),\n\t\tWaypointAt(i + 1),\n\t\tWaypointAt(i + 2),\n\t\tmath.min(t + 0.02, 1)\n\t)\n\tif (ahead - position).Magnitude > 1e-3 then drone.CFrame = CFrame.lookAt(position, ahead) end\nend)"},
"bz-chain":{"k":"S","what":"Two cubic curves joined smoothly: the second curve's first handle mirrors the first curve's last handle through the joint, so the cart flows through without a kink.","services":[],"variables":"","functions":"local function QuadBezier(p0, p1, p2, t)\n\treturn p0:Lerp(p1, t):Lerp(p1:Lerp(p2, t), t)\nend\n\nlocal function CubicBezier(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn p0 * oneMinusT ^ 3 + p1 * (3 * oneMinusT ^ 2 * t) + p2 * (3 * oneMinusT * t ^ 2) + p3 * t ^ 3\nend\n\nlocal function CubicTangent(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn (p1 - p0) * (3 * oneMinusT ^ 2) + (p2 - p1) * (6 * oneMinusT * t) + (p3 - p2) * (3 * t ^ 2)\nend","setup":"local curveA0, curveA1, curveA2, joint =\n\tORIGIN + Vector3.new(-18, 1, 0),\n\tORIGIN + Vector3.new(-14, 1, -12),\n\tORIGIN + Vector3.new(-4, 1, -8),\n\tORIGIN + Vector3.new(0, 1, 0)\n\nlocal curveB1 = joint + (joint - curveA2) -- mirror the handle: no corner at the joint\nlocal curveB2, curveB3 = ORIGIN + Vector3.new(14, 1, 12), ORIGIN + Vector3.new(18, 1, 0)\n\nfor i = 0, 60 do\n\tlocal t = i / 30\n\tlocal point = t <= 1 and CubicBezier(curveA0, curveA1, curveA2, joint, t)\n\t\tor CubicBezier(joint, curveB1, curveB2, curveB3, t - 1)\n\tMakePart(Vector3.new(0.3, 0.3, 0.3), point, Color3.fromRGB(90, 90, 100), { CanCollide = false })\nend\n\nlocal cart = MakePart(Vector3.new(2, 1, 3), curveA0, Color3.fromRGB(226, 133, 26), { CanCollide = false })","runtime":"runService.Heartbeat:Connect(function()\n\tlocal progress = (os.clock() * 0.4) % 2\n\tlocal onFirstCurve = progress < 1\n\tlocal t = onFirstCurve and progress or progress - 1\n\tlocal position = onFirstCurve and CubicBezier(curveA0, curveA1, curveA2, joint, t)\n\t\tor CubicBezier(joint, curveB1, curveB2, curveB3, t)\n\tlocal direction = onFirstCurve and CubicTangent(curveA0, curveA1, curveA2, joint, t)\n\t\tor CubicTangent(joint, curveB1, curveB2, curveB3, t)\n\tcart.CFrame =\n\t\tCFrame.lookAt(position + Vector3.new(0, 0.6, 0), position + Vector3.new(0, 0.6, 0) + direction)\nend)"},
"bz-closest":{"k":"S","what":"A curved rail. A marker shows the closest point on it to the nearest player (sampled, then refined), and it says \"GRIND\" when you are within 3 studs.","services":[],"variables":"","functions":"local function QuadBezier(p0, p1, p2, t)\n\treturn p0:Lerp(p1, t):Lerp(p1:Lerp(p2, t), t)\nend\n\nlocal function CubicBezier(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn p0 * oneMinusT ^ 3 + p1 * (3 * oneMinusT ^ 2 * t) + p2 * (3 * oneMinusT * t ^ 2) + p3 * t ^ 3\nend\n\nlocal function CubicTangent(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn (p1 - p0) * (3 * oneMinusT ^ 2) + (p2 - p1) * (6 * oneMinusT * t) + (p3 - p2) * (3 * t ^ 2)\nend","setup":"local p0, p1, p2, p3 =\n\tORIGIN + Vector3.new(-16, 3, 6),\n\tORIGIN + Vector3.new(-6, 8, -12),\n\tORIGIN + Vector3.new(6, 0, 12),\n\tORIGIN + Vector3.new(16, 3, -6)\n\nfor i = 0, 60 do\n\tMakePart(\n\t\tVector3.new(0.5, 0.5, 0.5),\n\t\tCubicBezier(p0, p1, p2, p3, i / 60),\n\t\tColor3.fromRGB(60, 60, 70),\n\t\t{ CanCollide = false }\n\t)\nend\n\nlocal marker = MakePart(\n\tVector3.new(1.2, 1.2, 1.2),\n\tp0,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n)\n\nlocal label = MakeLabel(marker)\n\nlocal function DistanceAt(t, point)\n\treturn (CubicBezier(p0, p1, p2, p3, t) - point).Magnitude\nend","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(marker.Position)\n\tif not root then return end\n\tlocal best, bestDistance = 0, math.huge\n\tfor i = 0, 50 do\n\t\tlocal distance = DistanceAt(i / 50, root.Position)\n\t\tif distance < bestDistance then\n\t\t\tbest, bestDistance = i / 50, distance\n\t\tend\n\tend\n\tlocal low, high = math.max(0, best - 0.02), math.min(1, best + 0.02)\n\tfor _ = 1, 20 do\n\t\tlocal third1, third2 = low + (high - low) / 3, high - (high - low) / 3\n\t\tif DistanceAt(third1, root.Position) < DistanceAt(third2, root.Position) then\n\t\t\thigh = third2\n\t\telse\n\t\t\tlow = third1\n\t\tend\n\tend\n\tlocal t = (low + high) / 2\n\tmarker.Position = CubicBezier(p0, p1, p2, p3, t)\n\tlocal distance = DistanceAt(t, root.Position)\n\tlabel.Text = string.format(\"t = %.2f   %.1f studs%s\", t, distance, distance < 3 and \"  GRIND\" or \"\")\nend)"},
"bz-offset":{"k":"S","what":"Builds a road along a cubic curve out of parts, with fence posts on both edges placed using tangent × up.","services":[],"variables":"local _segments = 40\nlocal _width = 6","functions":"local function QuadBezier(p0, p1, p2, t)\n\treturn p0:Lerp(p1, t):Lerp(p1:Lerp(p2, t), t)\nend\n\nlocal function CubicBezier(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn p0 * oneMinusT ^ 3 + p1 * (3 * oneMinusT ^ 2 * t) + p2 * (3 * oneMinusT * t ^ 2) + p3 * t ^ 3\nend\n\nlocal function CubicTangent(p0, p1, p2, p3, t)\n\tlocal oneMinusT = 1 - t\n\treturn (p1 - p0) * (3 * oneMinusT ^ 2) + (p2 - p1) * (6 * oneMinusT * t) + (p3 - p2) * (3 * t ^ 2)\nend","setup":"local p0, p1, p2, p3 =\n\tORIGIN + Vector3.new(-24, 0.2, 10),\n\tORIGIN + Vector3.new(-8, 0.2, -16),\n\tORIGIN + Vector3.new(8, 0.2, 16),\n\tORIGIN + Vector3.new(24, 0.2, -10)\n\nfor i = 0, _segments - 1 do\n\tlocal pointA = CubicBezier(p0, p1, p2, p3, i / _segments)\n\tlocal pointB = CubicBezier(p0, p1, p2, p3, (i + 1) / _segments)\n\tlocal road = MakePart(\n\t\tVector3.new(_width, 0.4, (pointB - pointA).Magnitude + 0.1),\n\t\tpointA,\n\t\tColor3.fromRGB(60, 60, 65)\n\t)\n\troad.CFrame = CFrame.lookAt((pointA + pointB) / 2, pointB)\n\tif i % 3 == 0 then\n\t\tlocal right = (pointB - pointA):Cross(Vector3.yAxis).Unit\n\t\tfor _, side in { -1, 1 } do\n\t\t\tMakePart(\n\t\t\t\tVector3.new(0.4, 2, 0.4),\n\t\t\t\tpointA + right * side * (_width / 2 + 0.5) + Vector3.new(0, 1, 0),\n\t\t\t\tColor3.fromRGB(240, 240, 240)\n\t\t\t)\n\t\tend\n\tend\nend","runtime":""},
"bz-frame":{"k":"S","what":"A loop-the-loop track. The cart's \"up\" is carried along the curve with rotation-minimising frames, so it stays on the inside of the loop instead of flipping.","services":[],"variables":"local _steps = 240","functions":"","setup":"local points = {}\n\nfor i = 0, _steps do\n\tlocal progress = i / _steps\n\tlocal angle = -math.pi + 2 * math.pi * progress\n\tpoints[i] = ORIGIN\n\t\t+ Vector3.new(\n\t\t\t4 * (progress * 2 * math.pi - math.pi) - 9 * math.sin(angle) * 0.5,\n\t\t\t2 + 6 * (1 + math.cos(angle)),\n\t\t\t4 * progress - 2\n\t\t)\n\tif i % 4 == 0 then\n\t\tMakePart(Vector3.new(0.4, 0.4, 0.4), points[i], Color3.fromRGB(60, 60, 70), { CanCollide = false })\n\tend\nend\n\nlocal tangents, upVectors = {}, {}\n\nfor i = 0, _steps do\n\ttangents[i] = (points[math.min(_steps, i + 1)] - points[math.max(0, i - 1)]).Unit\nend\n\nupVectors[0] = Vector3.yAxis\n\nfor i = 0, _steps - 1 do\n\tlocal step = points[i + 1] - points[i]\n\tlocal stepLengthSquared = step:Dot(step)\n\tlocal reflectedUp = upVectors[i] - step * (2 / stepLengthSquared * step:Dot(upVectors[i]))\n\tlocal reflectedTangent = tangents[i] - step * (2 / stepLengthSquared * step:Dot(tangents[i]))\n\tlocal tangentDifference = tangents[i + 1] - reflectedTangent\n\tlocal differenceSquared = tangentDifference:Dot(tangentDifference)\n\tupVectors[i + 1] = differenceSquared < 1e-12 and reflectedUp\n\t\tor (reflectedUp - tangentDifference * (2 / differenceSquared * tangentDifference:Dot(reflectedUp))).Unit\nend\n\nlocal cart =\n\tMakePart(Vector3.new(1.6, 0.8, 2.4), points[0], Color3.fromRGB(226, 133, 26), { CanCollide = false })","runtime":"runService.Heartbeat:Connect(function()\n\tlocal i = math.floor((os.clock() * 50) % _steps)\n\tlocal position = points[i] + upVectors[i] * 0.6\n\tcart.CFrame = CFrame.lookAt(position, position + tangents[i], upVectors[i])\nend)"},
"pr-weighted":{"k":"S","what":"Click the chest to roll a weighted loot table. The result and its real percentage show above it.","services":[],"variables":"","functions":"","setup":"local LOOT = { { \"Common\", 60 }, { \"Uncommon\", 25 }, { \"Rare\", 10 }, { \"Legendary\", 4 }, { \"Mythic\", 1 } }\nlocal total = 0\n\nfor _, item in LOOT do\n\ttotal += item[2]\nend\n\nlocal random = Random.new()\nlocal chest = MakePart(Vector3.new(4, 3, 3), ORIGIN + Vector3.new(0, 1.5, 0), Color3.fromRGB(140, 90, 40))\nlocal label = MakeLabel(chest, \"click me\")\nlocal clickDetector = Instance.new(\"ClickDetector\")\nclickDetector.Parent = chest","runtime":"clickDetector.MouseClick:Connect(function(player)\n\tlocal roll = random:NextNumber(0, total)\n\tfor _, item in LOOT do\n\t\troll -= item[2]\n\t\tif roll <= 0 then\n\t\t\tlabel.Text = string.format(\"%s: %s (%.0f%%)\", player.Name, item[1], item[2] / total * 100)\n\t\t\tbreak\n\t\tend\n\tend\nend)"},
"pr-atleast":{"k":"S","what":"Click the block to try for a 5% drop. It counts your tries and shows the chance you had of getting it by then: 1 − 0.95^n.","services":[],"variables":"local _chance = 0.05","functions":"","setup":"local random = Random.new()\nlocal block = MakePart(Vector3.new(4, 4, 4), ORIGIN + Vector3.new(0, 2, 0), Color3.fromRGB(163, 162, 165))\nlocal label = MakeLabel(block, \"click to try (5% chance)\")\nlocal clickDetector = Instance.new(\"ClickDetector\")\nclickDetector.Parent = block\nlocal tries = 0","runtime":"clickDetector.MouseClick:Connect(function()\n\ttries += 1\n\tlocal chanceByNow = 1 - (1 - _chance) ^ tries\n\tif random:NextNumber() < _chance then\n\t\tlabel.Text =\n\t\t\tstring.format(\"GOT IT on try %d (%.0f%% of players have it by now)\", tries, chanceByNow * 100)\n\t\tblock.Color = Color3.fromRGB(250, 200, 40)\n\t\ttries = 0\n\telse\n\t\tlabel.Text = string.format(\"try %d: nothing (%.0f%% would have it by now)\", tries, chanceByNow * 100)\n\t\tblock.Color = Color3.fromRGB(163, 162, 165)\n\tend\nend)\n\nprint(\"tries for a 50% chance:\", math.ceil(math.log(0.5) / math.log(1 - _chance)))"},
"pr-dice":{"k":"S","what":"Rolls 2d6 ten thousand times and builds a bar chart of the totals: the middle values come up most.","services":[],"variables":"","functions":"","setup":"local random = Random.new()\nlocal counts = {}\n\nfor total = 2, 12 do\n\tcounts[total] = 0\nend\n\nfor _ = 1, 10000 do\n\tlocal total = random:NextInteger(1, 6) + random:NextInteger(1, 6)\n\tcounts[total] += 1\nend\n\nfor total = 2, 12 do\n\tlocal height = counts[total] / 10000 * 60\n\tlocal bar = MakePart(\n\t\tVector3.new(1.6, height, 1.6),\n\t\tORIGIN + Vector3.new((total - 7) * 2, height / 2, 0),\n\t\tColor3.fromHSV(0.08, 0.7, 0.6 + height / 30)\n\t)\n\tMakeLabel(bar, string.format(\"%d: %.1f%%\", total, counts[total] / 100))\nend","runtime":""},
"pr-spread":{"k":"S","what":"A gun fires 40 bullets at a wall with bell-curve (gaussian) spread; marks show where they hit, bunched near the centre.","services":[],"variables":"local _spread = math.rad(3)","functions":"","setup":"local random = Random.new()\n\nlocal function Gaussian()\n\tlocal uniform1, uniform2 = 1 - random:NextNumber(), random:NextNumber()\n\treturn math.sqrt(-2 * math.log(uniform1)) * math.cos(2 * math.pi * uniform2)\nend\n\nlocal wall = MakePart(Vector3.new(20, 16, 1), ORIGIN + Vector3.new(0, 8, -20), Color3.fromRGB(230, 230, 230))\nlocal gun = MakePart(Vector3.new(1, 1, 2), ORIGIN + Vector3.new(0, 8, 10), Color3.fromRGB(60, 60, 70))\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterDescendantsInstances = { gun }","runtime":"while true do\n\tfor _ = 1, 40 do\n\t\tlocal shot = CFrame.lookAt(gun.Position, wall.Position)\n\t\t\t* CFrame.Angles(Gaussian() * _spread, Gaussian() * _spread, 0)\n\t\tlocal hit = workspace:Raycast(gun.Position, shot.LookVector * 100, raycastParams)\n\t\tif hit then\n\t\t\tlocal mark = MakePart(\n\t\t\t\tVector3.new(0.4, 0.4, 0.1),\n\t\t\t\thit.Position,\n\t\t\t\tColor3.fromRGB(230, 60, 60),\n\t\t\t\t{ CanCollide = false, CanQuery = false }\n\t\t\t)\n\t\t\ttask.delay(4, function()\n\t\t\t\tmark:Destroy()\n\t\t\tend)\n\t\tend\n\t\ttask.wait(0.05)\n\tend\n\ttask.wait(3)\nend"},
"pr-shuffle":{"k":"S","what":"A lamp changes colour every half second using a shuffle bag: every colour comes up once before any repeats.","services":[],"variables":"","functions":"","setup":"local COLORS = {\n\tColor3.fromRGB(230, 60, 60),\n\tColor3.fromRGB(60, 200, 90),\n\tColor3.fromRGB(70, 130, 240),\n\tColor3.fromRGB(250, 200, 40),\n}\n\nlocal random = Random.new()\nlocal bag = {}\n\nlocal function NextColor()\n\tif #bag == 0 then\n\t\tfor _, color in COLORS do\n\t\t\ttable.insert(bag, color)\n\t\tend\n\t\tfor i = #bag, 2, -1 do -- Fisher–Yates shuffle\n\t\t\tlocal j = random:NextInteger(1, i)\n\t\t\tbag[i], bag[j] = bag[j], bag[i]\n\t\tend\n\tend\n\treturn table.remove(bag)\nend\n\nlocal lamp = MakePart(\n\tVector3.new(4, 4, 4),\n\tORIGIN + Vector3.new(0, 2, 0),\n\tCOLORS[1],\n\t{ Material = Enum.Material.Neon }\n)","runtime":"while true do\n\tlamp.Color = NextColor()\n\ttask.wait(0.5)\nend"},
"pr-ev":{"k":"S","what":"Works out the expected value of a crate, then opens 10,000 simulated crates and prints the average and profit.","services":[],"variables":"local _price = 30","functions":"","setup":"local REWARDS = {\n\t{ Amount = 10, Chance = 0.73 },\n\t{ Amount = 50, Chance = 0.25 },\n\t{ Amount = 500, Chance = 0.02 },\n}\n\nlocal expected = 0\n\nfor _, reward in REWARDS do\n\texpected += reward.Amount * reward.Chance\nend\n\nlocal random = Random.new()\nlocal sum = 0\n\nfor _ = 1, 10000 do\n\tlocal roll = random:NextNumber()\n\tfor _, reward in REWARDS do\n\t\troll -= reward.Chance\n\t\tif roll <= 0 then\n\t\t\tsum += reward.Amount\n\t\t\tbreak\n\t\tend\n\tend\nend\n\nlocal crate = MakePart(Vector3.new(4, 4, 4), ORIGIN + Vector3.new(0, 2, 0), Color3.fromRGB(140, 90, 40))\nMakeLabel(crate, string.format(\"EV %.1f, simulated %.1f, price %d\", expected, sum / 10000, _price))\nprint(\"expected value:\", expected, \"simulated:\", sum / 10000, \"player profit per crate:\", expected - _price)","runtime":""},
"m-random":{"k":"S","what":"Scatters 80 coins evenly inside a circle: random angle, and radius × math.sqrt(random) so they don't bunch in the middle.","services":[],"variables":"local _radius = 16","functions":"","setup":"local random = Random.new()\n\nfor _ = 1, 80 do\n\tlocal angle = random:NextNumber(0, 2 * math.pi)\n\tlocal distance = _radius * math.sqrt(random:NextNumber())\n\tMakePart(\n\t\tVector3.new(0.3, 1.5, 1.5),\n\t\tORIGIN + Vector3.new(math.cos(angle) * distance, 1, math.sin(angle) * distance),\n\t\tColor3.fromRGB(250, 200, 40),\n\t\t{\n\t\t\tShape = Enum.PartType.Cylinder,\n\t\t\tOrientation = Vector3.new(0, 0, 90),\n\t\t\tMaterial = Enum.Material.Neon,\n\t\t}\n\t)\nend","runtime":""},
"pr-prd":{"k":"S","what":"Click the dummy to attack. Crits use a rising chance (C × hits since the last crit), which averages 25% but never streaks badly.","services":[],"variables":"local _critStep = 0.0847 -- gives about 25% crits on average","functions":"","setup":"local random = Random.new()\nlocal dummy = MakePart(Vector3.new(3, 5, 2), ORIGIN + Vector3.new(0, 2.5, 0), Color3.fromRGB(163, 162, 165))\nlocal label = MakeLabel(dummy, \"click to attack\")\nlocal clickDetector = Instance.new(\"ClickDetector\")\nclickDetector.Parent = dummy\nlocal hitsSinceCrit, hits, crits = 0, 0, 0","runtime":"clickDetector.MouseClick:Connect(function()\n\thitsSinceCrit += 1\n\thits += 1\n\tlocal chance = _critStep * hitsSinceCrit\n\tif random:NextNumber() < chance then\n\t\tcrits += 1\n\t\thitsSinceCrit = 0\n\t\tdummy.Color = Color3.fromRGB(250, 200, 40)\n\t\tlabel.Text = string.format(\"CRIT! (chance was %.0f%%)  %d/%d crits\", chance * 100, crits, hits)\n\telse\n\t\tdummy.Color = Color3.fromRGB(163, 162, 165)\n\t\tlabel.Text = string.format(\"hit (crit chance %.0f%%)  %d/%d crits\", chance * 100, crits, hits)\n\tend\nend)"},
"pr-events":{"k":"S","what":"Meteors fall at an average of 0.5 per second, rolled every frame with chance = 1 − exp(−rate × dt), so the rate is the same at any frame rate.","services":[],"variables":"local _rate = 0.5","functions":"","setup":"local random = Random.new()","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tif random:NextNumber() < 1 - math.exp(-_rate * deltaTime) then\n\t\tlocal spot = ORIGIN + Vector3.new(random:NextNumber(-20, 20), 0, random:NextNumber(-20, 20))\n\t\tlocal meteor = MakePart(\n\t\t\tVector3.new(2, 2, 2),\n\t\t\tspot + Vector3.new(0, 60, 0),\n\t\t\tColor3.fromRGB(255, 120, 40),\n\t\t\t{ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, CanCollide = false }\n\t\t)\n\t\tlocal tween = tweenService:Create(\n\t\t\tmeteor,\n\t\t\tTweenInfo.new(1, Enum.EasingStyle.Quad, Enum.EasingDirection.In),\n\t\t\t{ Position = spot }\n\t\t)\n\t\ttween:Play()\n\t\ttween.Completed:Connect(function()\n\t\t\tlocal explosion = Instance.new(\"Explosion\")\n\t\t\texplosion.Position = spot\n\t\t\texplosion.BlastPressure = 0\n\t\t\texplosion.DestroyJointRadiusPercent = 0\n\t\t\texplosion.Parent = workspace\n\t\t\tmeteor:Destroy()\n\t\tend)\n\tend\nend)"},
"pr-montecarlo":{"k":"S","what":"Estimates π by throwing 20,000 random points into a square, and shows 400 of them (inside the circle in orange).","services":[],"variables":"local _size = 10","functions":"","setup":"local random = Random.new()\nlocal inside = 0\n\nfor i = 1, 20000 do\n\tlocal x, z = random:NextNumber(-1, 1), random:NextNumber(-1, 1)\n\tlocal hit = x * x + z * z <= 1\n\tif hit then\n\t\tinside += 1\n\tend\n\tif i <= 400 then\n\t\tMakePart(\n\t\t\tVector3.new(0.3, 0.3, 0.3),\n\t\t\tORIGIN + Vector3.new(x * _size, 0.2, z * _size),\n\t\t\thit and Color3.fromRGB(226, 133, 26) or Color3.fromRGB(120, 120, 130),\n\t\t\t{ CanCollide = false }\n\t\t)\n\tend\nend\n\nlocal estimate = 4 * inside / 20000\nlocal sign = MakePart(Vector3.new(1, 1, 1), ORIGIN + Vector3.new(0, 3, 0), Color3.new(1, 1, 1))\nMakeLabel(sign, string.format(\"pi is about %.4f\", estimate))\nprint(\"pi estimate:\", estimate)","runtime":""},
"rc-basic":{"k":"S","what":"A sweeping scanner fires a 40-stud ray each frame. The beam stops where it hits and the label shows the Instance name and Distance.","services":[],"variables":"","functions":"","setup":"local scanner = MakePart(Vector3.new(1.5, 1.5, 2), ORIGIN + Vector3.new(0, 3, 10), Color3.fromRGB(60, 60, 70))\n\nMakePart(\n\tVector3.new(4, 6, 4),\n\tORIGIN + Vector3.new(-6, 3, -6),\n\tColor3.fromRGB(140, 90, 40),\n\t{ Name = \"Crate\" }\n)\n\nMakePart(\n\tVector3.new(12, 6, 1),\n\tORIGIN + Vector3.new(4, 3, -14),\n\tColor3.fromRGB(90, 90, 100),\n\t{ Name = \"Wall\" }\n)\n\nlocal beam = MakeLinePart(Color3.fromRGB(255, 60, 60))\nlocal label = MakeLabel(scanner)\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterDescendantsInstances = { scanner, beam }","runtime":"runService.Heartbeat:Connect(function()\n\tscanner.CFrame = CFrame.new(scanner.Position) * CFrame.Angles(0, math.sin(os.clock() * 0.6) * 0.9, 0)\n\tlocal origin, direction = scanner.Position, scanner.CFrame.LookVector * 40 -- direction AND range\n\tlocal result = workspace:Raycast(origin, direction, raycastParams)\n\tDrawLine(beam, origin, result and result.Position or origin + direction)\n\tlabel.Text = result and string.format(\"hit %s at %.1f studs\", result.Instance.Name, result.Distance)\n\t\tor \"nil (nothing in 40 studs)\"\nend)"},
"rc-filter":{"k":"S","what":"A laser behind a glass pane. The ray uses RaycastParams to Exclude the glass, so it hits the crate behind it.","services":[],"variables":"","functions":"","setup":"local emitter =\n\tMakePart(Vector3.new(1.5, 1.5, 1.5), ORIGIN + Vector3.new(0, 3, 12), Color3.fromRGB(60, 60, 70))\n\nlocal glass = MakePart(\n\tVector3.new(10, 8, 0.3),\n\tORIGIN + Vector3.new(0, 4, 4),\n\tColor3.fromRGB(150, 200, 255),\n\t{ Name = \"Glass\", Transparency = 0.6 }\n)\n\nlocal crate = MakePart(\n\tVector3.new(4, 6, 4),\n\tORIGIN + Vector3.new(0, 3, -6),\n\tColor3.fromRGB(140, 90, 40),\n\t{ Name = \"Crate\" }\n)\n\nlocal beam = MakeLinePart(Color3.fromRGB(255, 60, 60))\nlocal label = MakeLabel(emitter)\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterType = Enum.RaycastFilterType.Exclude\nraycastParams.FilterDescendantsInstances = { emitter, beam, glass } -- the ray passes through all of these","runtime":"runService.Heartbeat:Connect(function()\n\tlocal direction = (crate.Position - emitter.Position).Unit * 40\n\tlocal result = workspace:Raycast(emitter.Position, direction, raycastParams)\n\tDrawLine(beam, emitter.Position, result and result.Position or emitter.Position + direction)\n\tlabel.Text = \"hit: \" .. (result and result.Instance.Name or \"nothing\")\nend)"},
"rc-los":{"k":"S","what":"A guard checks range, then its view cone, then a raycast for walls. It turns red only when it can really see you.","services":[],"variables":"local _range = 40\nlocal _halfViewAngle = math.rad(50)","functions":"","setup":"local guard = MakePart(Vector3.new(3, 5, 2), ORIGIN + Vector3.new(0, 2.5, 0), Color3.fromRGB(90, 160, 230))\nMakePart(Vector3.new(8, 8, 1), ORIGIN + Vector3.new(6, 4, -10), Color3.fromRGB(90, 90, 100))\nMakePart(Vector3.new(3, 3, 3), ORIGIN + Vector3.new(-6, 1.5, -8), Color3.fromRGB(140, 90, 40))\nlocal label = MakeLabel(guard)\nlocal raycastParams = RaycastParams.new()","runtime":"runService.Heartbeat:Connect(function()\n\tguard.CFrame = CFrame.new(guard.Position) * CFrame.Angles(0, math.sin(os.clock() * 0.5) * 0.8, 0)\n\tlocal root = GetNearestRoot(guard.Position)\n\tlocal reason = \"nobody here\"\n\tif root then\n\t\tlocal offset = root.Position - guard.Position\n\t\tif offset.Magnitude > _range then\n\t\t\treason = \"too far\"\n\t\telseif guard.CFrame.LookVector:Dot(offset.Unit) < math.cos(_halfViewAngle) then\n\t\t\treason = \"outside the cone\"\n\t\telse\n\t\t\traycastParams.FilterDescendantsInstances = { guard, root.Parent }\n\t\t\treason = workspace:Raycast(guard.Position, offset, raycastParams) and \"behind a wall\" or \"SPOTTED\"\n\t\tend\n\tend\n\tguard.Color = reason == \"SPOTTED\" and Color3.fromRGB(230, 60, 60) or Color3.fromRGB(90, 160, 230)\n\tlabel.Text = reason\nend)"},
"rc-mouse":{"k":"L","what":"Click anywhere: a ray from the camera through the mouse (ViewportPointToRay) finds the spot and drops a block there, on your screen only.","services":["UserInputService"],"variables":"","functions":"","setup":"local raycastParams = RaycastParams.new()","runtime":"userInputService.InputBegan:Connect(function(input, gameProcessed)\n\tif gameProcessed or input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end\n\tlocal mousePosition = userInputService:GetMouseLocation()\n\tlocal ray = camera:ViewportPointToRay(mousePosition.X, mousePosition.Y)\n\traycastParams.FilterDescendantsInstances = { player.Character }\n\tlocal result = workspace:Raycast(ray.Origin, ray.Direction * 500, raycastParams)\n\tif result then\n\t\tMakePart(Vector3.new(2, 2, 2), result.Position + result.Normal, Color3.fromHSV(math.random(), 0.6, 1))\n\tend\nend)"},
"rc-surface":{"k":"S","what":"Drops a sign onto random spots of a bumpy area: a ray down finds the ground, and the sign is stood on the surface Normal.","services":[],"variables":"","functions":"","setup":"MakePart(\n\tVector3.new(16, 1, 12),\n\tORIGIN + Vector3.new(-8, 2, 0),\n\tColor3.fromRGB(110, 150, 90),\n\t{ Orientation = Vector3.new(0, 0, 20) }\n)\n\nMakePart(\n\tVector3.new(12, 1, 12),\n\tORIGIN + Vector3.new(8, 2, 0),\n\tColor3.fromRGB(110, 150, 90),\n\t{ Orientation = Vector3.new(-25, 0, 0) }\n)\n\nlocal sign = MakePart(Vector3.new(2, 3, 0.4), ORIGIN, Color3.fromRGB(226, 133, 26), { CanCollide = false })\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterDescendantsInstances = { sign }\nlocal random = Random.new()","runtime":"while true do\n\tlocal top = ORIGIN + Vector3.new(random:NextNumber(-14, 14), 30, random:NextNumber(-6, 6))\n\tlocal result = workspace:Raycast(top, Vector3.new(0, -60, 0), raycastParams)\n\tif result then\n\t\tlocal up = result.Normal\n\t\tlocal forward = Vector3.new(0, 0, -1)\n\t\tforward = (forward - up * forward:Dot(up)).Unit -- flatten onto the surface\n\t\tlocal position = result.Position + up * 1.5\n\t\tsign.CFrame = CFrame.lookAt(position, position + forward, up)\n\tend\n\ttask.wait(1)\nend"},
"rc-pierce":{"k":"S","what":"A railgun fires through up to 3 walls in a line. Each hit is excluded and the ray continues, losing 35% damage per wall.","services":[],"variables":"","functions":"","setup":"local gun = MakePart(Vector3.new(1.5, 1.5, 3), ORIGIN + Vector3.new(0, 3, 16), Color3.fromRGB(60, 60, 70))\n\nfor i = 1, 4 do\n\tMakePart(\n\t\tVector3.new(8, 6, 0.6),\n\t\tORIGIN + Vector3.new(0, 3, 10 - i * 6),\n\t\tColor3.fromHSV(i / 5, 0.4, 0.8),\n\t\t{ Name = \"Wall\" .. i }\n\t)\nend\n\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterType = Enum.RaycastFilterType.Exclude","runtime":"while true do\n\tlocal ignore = { gun }\n\tlocal origin, direction, damage =\n\t\tgun.Position, Vector3.new(math.random(-10, 10) / 100, 0, -1).Unit * 100, 100\n\tfor _ = 0, 3 do\n\t\traycastParams.FilterDescendantsInstances = ignore\n\t\tlocal result = workspace:Raycast(origin, direction, raycastParams)\n\t\tif not result then break end\n\t\tlocal beam = MakeLinePart(Color3.fromRGB(255, 60, 60))\n\t\tDrawLine(beam, origin, result.Position)\n\t\tlocal spark = MakePart(\n\t\t\tVector3.new(0.8, 0.8, 0.8),\n\t\t\tresult.Position,\n\t\t\tColor3.fromRGB(250, 200, 40),\n\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t\t)\n\t\tMakeLabel(spark, string.format(\"%s: %.0f dmg\", result.Instance.Name, damage))\n\t\ttask.delay(1.5, function()\n\t\t\tbeam:Destroy()\n\t\t\tspark:Destroy()\n\t\tend)\n\t\tdamage *= 0.65\n\t\ttable.insert(ignore, result.Instance)\n\t\torigin = result.Position\n\tend\n\ttask.wait(2)\nend"},
"rc-shapecast":{"k":"S","what":"Two shots toward a narrow gap: a thin Raycast slips through, a radius-1.2 Spherecast clips a pillar.","services":[],"variables":"","functions":"","setup":"MakePart(\n\tVector3.new(4, 6, 2),\n\tORIGIN + Vector3.new(-2.8, 3, -4),\n\tColor3.fromRGB(90, 90, 100),\n\t{ Name = \"PillarL\" }\n)\n\nMakePart(\n\tVector3.new(4, 6, 2),\n\tORIGIN + Vector3.new(2.8, 3, -4),\n\tColor3.fromRGB(90, 90, 100),\n\t{ Name = \"PillarR\" }\n)\n\nMakePart(\n\tVector3.new(16, 8, 1),\n\tORIGIN + Vector3.new(0, 4, -16),\n\tColor3.fromRGB(140, 90, 40),\n\t{ Name = \"BackWall\" }\n)\n\nlocal origin = ORIGIN + Vector3.new(0, 3, 10)\nlocal direction = Vector3.new(0, 0, -40)\nlocal rayResult = workspace:Raycast(origin, direction)\nlocal sphereResult = workspace:Spherecast(origin, 1.2, direction)\nlocal thinLine = MakeLinePart(Color3.fromRGB(120, 120, 130))\nDrawLine(thinLine, origin, rayResult and rayResult.Position or origin + direction)\n\nlocal ball = MakePart(\n\tVector3.new(2.4, 2.4, 2.4),\n\torigin,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, Transparency = 0.5, CanCollide = false, CanQuery = false }\n)\n\nif sphereResult then ball.Position = origin + direction.Unit * sphereResult.Distance end\n\nMakeLabel(\n\tball,\n\tstring.format(\n\t\t\"Raycast: %s   Spherecast: %s\",\n\t\trayResult and rayResult.Instance.Name or \"nil\",\n\t\tsphereResult and sphereResult.Instance.Name or \"nil\"\n\t)\n)","runtime":""},
"rc-bounce":{"k":"S","what":"A rotating emitter fires a laser that ricochets up to 6 times around a room: raycast, reflect off the Normal, repeat.","services":[],"variables":"","functions":"local function MakeRoom(size, height)\n\tfor _, wall in\n\t\t{\n\t\t\t{ Vector3.new(size * 2, height, 1), Vector3.new(0, height / 2, -size) },\n\t\t\t{ Vector3.new(size * 2, height, 1), Vector3.new(0, height / 2, size) },\n\t\t\t{ Vector3.new(1, height, size * 2), Vector3.new(-size, height / 2, 0) },\n\t\t\t{ Vector3.new(1, height, size * 2), Vector3.new(size, height / 2, 0) },\n\t\t}\n\tdo\n\t\tMakePart(wall[1], ORIGIN + wall[2], Color3.fromRGB(90, 90, 100))\n\tend\nend","setup":"MakeRoom(16, 6)\n\nMakePart(\n\tVector3.new(4, 6, 4),\n\tORIGIN + Vector3.new(5, 3, -5),\n\tColor3.fromRGB(150, 80, 160),\n\t{ Orientation = Vector3.new(0, 30, 0) }\n)\n\nlocal emitter =\n\tMakePart(Vector3.new(1.5, 1.5, 2.5), ORIGIN + Vector3.new(0, 3, 0), Color3.fromRGB(60, 60, 70))\n\nlocal beams = {}\n\nfor i = 1, 6 do\n\tbeams[i] = MakeLinePart(Color3.fromRGB(255, 60, 60))\nend\n\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterDescendantsInstances = { emitter, table.unpack(beams) }","runtime":"runService.Heartbeat:Connect(function()\n\temitter.CFrame = CFrame.new(emitter.Position) * CFrame.Angles(0, os.clock() * 0.4, 0)\n\tlocal origin, direction = emitter.Position, emitter.CFrame.LookVector\n\tfor i, beam in beams do\n\t\tbeam.Transparency = 1\n\tend\n\tfor i = 1, 6 do\n\t\tlocal result = workspace:Raycast(origin, direction * 100, raycastParams)\n\t\tlocal hit = result and result.Position or origin + direction * 100\n\t\tDrawLine(beams[i], origin, hit)\n\t\tbeams[i].Transparency = 0\n\t\tif not result then break end\n\t\tlocal normal = result.Normal\n\t\tdirection = direction - 2 * direction:Dot(normal) * normal\n\t\torigin = result.Position + normal * 0.01\n\tend\nend)"},
"rc-overlap":{"k":"S","what":"Every 3 seconds an explosion finds crates with GetPartBoundsInRadius, skips ones hidden behind the wall (raycast), and pushes the rest away.","services":[],"variables":"local _radius = 12","functions":"","setup":"local random = Random.new()\nlocal crates = {}\n\nfor i = 1, 14 do\n\tcrates[i] = MakePart(\n\t\tVector3.new(2, 2, 2),\n\t\tORIGIN + Vector3.new(random:NextNumber(-12, 12), 1, random:NextNumber(-12, 12)),\n\t\tColor3.fromRGB(140, 90, 40),\n\t\t{ Anchored = false, Name = \"Crate\" }\n\t)\nend\n\nlocal wall = MakePart(Vector3.new(1, 6, 10), ORIGIN + Vector3.new(4, 3, 0), Color3.fromRGB(90, 90, 100))\nlocal center = ORIGIN + Vector3.new(0, 1, 0)\nlocal overlapParams = OverlapParams.new()\noverlapParams.FilterType = Enum.RaycastFilterType.Include\noverlapParams.FilterDescendantsInstances = crates\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterType = Enum.RaycastFilterType.Include\nraycastParams.FilterDescendantsInstances = { wall }","runtime":"while true do\n\ttask.wait(3)\n\tlocal explosion = Instance.new(\"Explosion\")\n\texplosion.Position = center\n\texplosion.BlastPressure = 0\n\texplosion.DestroyJointRadiusPercent = 0\n\texplosion.Parent = workspace\n\tfor _, crate in workspace:GetPartBoundsInRadius(center, _radius, overlapParams) do\n\t\tlocal offset = crate.Position - center\n\t\tif not workspace:Raycast(center, offset, raycastParams) then -- nothing solid in between\n\t\t\tlocal strength = 1 - math.clamp(offset.Magnitude / _radius, 0, 1)\n\t\t\tcrate:ApplyImpulse((offset.Unit + Vector3.new(0, 1, 0)) * strength * 120 * crate.AssemblyMass)\n\t\tend\n\tend\nend"},
"rc-hover":{"k":"S","what":"A hoverboard glides back and forth over ramps. Four rays down measure the ground; it floats at the average height and tilts with the average Normal.","services":[],"variables":"local _hoverHeight = 1.5","functions":"","setup":"MakePart(\n\tVector3.new(8, 1, 8),\n\tORIGIN + Vector3.new(-8, 1, 0),\n\tColor3.fromRGB(110, 150, 90),\n\t{ Orientation = Vector3.new(0, 0, 15) }\n)\n\nMakePart(\n\tVector3.new(6, 1, 8),\n\tORIGIN + Vector3.new(2, 0.8, 0),\n\tColor3.fromRGB(110, 150, 90),\n\t{ Orientation = Vector3.new(0, 0, -20) }\n)\n\nMakePart(\n\tVector3.new(8, 1, 8),\n\tORIGIN + Vector3.new(11, 1.2, 0),\n\tColor3.fromRGB(110, 150, 90),\n\t{ Orientation = Vector3.new(0, 0, 10) }\n)\n\nlocal board = MakePart(\n\tVector3.new(4, 0.4, 2),\n\tORIGIN + Vector3.new(0, 3, 0),\n\tColor3.fromRGB(226, 133, 26),\n\t{ CanCollide = false }\n)\n\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterDescendantsInstances = { board }\n\nlocal CORNERS = {\n\tVector3.new(-1.8, 0, -0.9),\n\tVector3.new(1.8, 0, -0.9),\n\tVector3.new(-1.8, 0, 0.9),\n\tVector3.new(1.8, 0, 0.9),\n}","runtime":"runService.Heartbeat:Connect(function()\n\tlocal x = math.sin(os.clock() * 0.4) * 16\n\tlocal heightSum, normalSum, count = 0, Vector3.zero, 0\n\tfor _, corner in CORNERS do\n\t\tlocal origin = ORIGIN + Vector3.new(x + corner.X, 10, corner.Z)\n\t\tlocal result = workspace:Raycast(origin, Vector3.new(0, -20, 0), raycastParams)\n\t\tif result then\n\t\t\theightSum += result.Position.Y\n\t\t\tnormalSum += result.Normal\n\t\t\tcount += 1\n\t\tend\n\tend\n\tif count == 0 then return end\n\tlocal up = (normalSum / count).Unit\n\tlocal position = Vector3.new(ORIGIN.X + x, heightSum / count + _hoverHeight, ORIGIN.Z)\n\tlocal forward = Vector3.xAxis - up * Vector3.xAxis:Dot(up)\n\tboard.CFrame = CFrame.lookAt(position, position + forward.Unit, up)\nend)"},
"rc-ccd":{"k":"S","what":"A very fast bullet (200 studs/s) still stops at a thin wall, because each frame it raycasts from its last position to its new one.","services":[],"variables":"","functions":"","setup":"local wall = MakePart(Vector3.new(10, 8, 0.2), ORIGIN + Vector3.new(0, 4, -10), Color3.fromRGB(90, 90, 100))\nlocal gun = MakePart(Vector3.new(1, 1, 2), ORIGIN + Vector3.new(0, 4, 20), Color3.fromRGB(60, 60, 70))\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterDescendantsInstances = { gun }","runtime":"while true do\n\tlocal bullet = MakePart(\n\t\tVector3.new(0.5, 0.5, 1.5),\n\t\tgun.Position,\n\t\tColor3.fromRGB(250, 200, 40),\n\t\t{ CanCollide = false, CanQuery = false, Material = Enum.Material.Neon }\n\t)\n\tlocal velocity = Vector3.new(0, 0, -200)\n\tlocal lastPosition = gun.Position\n\twhile true do\n\t\tlocal deltaTime = runService.Heartbeat:Wait()\n\t\tlocal nextPosition = lastPosition + velocity * deltaTime\n\t\tlocal result = workspace:Raycast(lastPosition, nextPosition - lastPosition, raycastParams) -- the whole stretch, not just the end\n\t\tif result then\n\t\t\tbullet.Position = result.Position\n\t\t\tlocal mark = MakePart(\n\t\t\t\tVector3.new(0.6, 0.6, 0.1),\n\t\t\t\tresult.Position,\n\t\t\t\tColor3.fromRGB(230, 60, 60),\n\t\t\t\t{ CanCollide = false, CanQuery = false }\n\t\t\t)\n\t\t\ttask.delay(1, function()\n\t\t\t\tmark:Destroy()\n\t\t\tend)\n\t\t\tbreak\n\t\tend\n\t\tbullet.Position = nextPosition\n\t\tlastPosition = nextPosition\n\t\tif (lastPosition - gun.Position).Magnitude > 100 then break end\n\tend\n\tbullet:Destroy()\n\ttask.wait(1)\nend"},
"bw-binary":{"k":"S","what":"A row of 8 lamps shows a number counting up in binary, one bit per lamp (lit = 1).","services":[],"variables":"","functions":"","setup":"local lamps = {}\n\nfor bit = 0, 7 do\n\tlamps[bit] = MakePart(\n\t\tVector3.new(1.6, 1.6, 1.6),\n\t\tORIGIN + Vector3.new((3.5 - bit) * 2, 2, 0),\n\t\tColor3.fromRGB(60, 60, 70)\n\t)\n\tMakeLabel(lamps[bit], tostring(2 ^ bit))\nend\n\nlocal sign = MakePart(\n\tVector3.new(1, 1, 1),\n\tORIGIN + Vector3.new(0, 6, 0),\n\tColor3.new(1, 1, 1),\n\t{ Transparency = 1, CanCollide = false }\n)\n\nlocal label = MakeLabel(sign)\nlocal number = 0","runtime":"while true do\n\tfor bit = 0, 7 do\n\t\tlocal isOn = bit32.extract(number, bit) == 1\n\t\tlamps[bit].Color = isOn and Color3.fromRGB(226, 133, 26) or Color3.fromRGB(60, 60, 70)\n\t\tlamps[bit].Material = isOn and Enum.Material.Neon or Enum.Material.SmoothPlastic\n\tend\n\tlabel.Text = string.format(\"%d = 0x%02X\", number, number)\n\tnumber = (number + 1) % 256\n\ttask.wait(0.4)\nend"},
"bw-flags":{"k":"S","what":"Click the four buttons to flip status flags with bit32.bxor; the dummy reads them with bit32.btest.","services":[],"variables":"","functions":"","setup":"local FLAGS = { Stunned = 1, OnFire = 2, Shielded = 4, Invisible = 8 }\nlocal ORDER = { \"Stunned\", \"OnFire\", \"Shielded\", \"Invisible\" }\nlocal dummy = MakePart(Vector3.new(3, 5, 2), ORIGIN + Vector3.new(0, 2.5, 0), Color3.fromRGB(160, 160, 170))\nlocal label = MakeLabel(dummy)\nlocal state = 0\n\nlocal function Refresh()\n\tdummy.Color = bit32.btest(state, FLAGS.OnFire) and Color3.fromRGB(255, 120, 30)\n\t\tor Color3.fromRGB(160, 160, 170)\n\tdummy.Material = bit32.btest(state, FLAGS.Shielded) and Enum.Material.ForceField\n\t\tor Enum.Material.SmoothPlastic\n\tdummy.Transparency = bit32.btest(state, FLAGS.Invisible) and 0.8 or 0\n\tlabel.Text = \"state = \" .. state\nend\n\nfor i, name in ORDER do\n\tlocal button = MakePart(\n\t\tVector3.new(3, 1, 3),\n\t\tORIGIN + Vector3.new(-6 + (i - 1) * 4, 0.5, 6),\n\t\tColor3.fromHSV(i / 5, 0.6, 0.9)\n\t)\n\tMakeLabel(button, name .. \" = \" .. FLAGS[name])\n\tlocal clickDetector = Instance.new(\"ClickDetector\")\n\tclickDetector.Parent = button\n\tclickDetector.MouseClick:Connect(function()\n\t\tstate = bit32.bxor(state, FLAGS[name])\n\t\tRefresh()\n\tend)\nend\n\nRefresh()","runtime":""},
"bw-ops":{"k":"S","what":"Prints AND, OR, XOR and NOT for two numbers in binary, and shows each result as a row of lamps.","services":[],"variables":"","functions":"local function ToBinary(number)\n\tlocal text = \"\"\n\tfor i = 7, 0, -1 do\n\t\ttext ..= bit32.extract(number, i)\n\tend\n\treturn text\nend","setup":"local A, B = 0b11001010, 0b10101100\n\nlocal results = {\n\t{ \"A\", A },\n\t{ \"B\", B },\n\t{ \"band\", bit32.band(A, B) },\n\t{ \"bor\", bit32.bor(A, B) },\n\t{ \"bxor\", bit32.bxor(A, B) },\n\t{ \"bnot A\", bit32.band(bit32.bnot(A), 0xFF) },\n}\n\nfor row, result in results do\n\tfor bit = 0, 7 do\n\t\tlocal isOn = bit32.extract(result[2], bit) == 1\n\t\tMakePart(\n\t\t\tVector3.new(1.4, isOn and 1.4 or 0.4, 1.4),\n\t\t\tORIGIN + Vector3.new((3.5 - bit) * 1.8, 1, (row - 3) * 2.4),\n\t\t\tisOn and Color3.fromRGB(226, 133, 26) or Color3.fromRGB(70, 70, 80)\n\t\t)\n\tend\n\tlocal tag = MakePart(\n\t\tVector3.new(0.5, 0.5, 0.5),\n\t\tORIGIN + Vector3.new(-9, 1, (row - 3) * 2.4),\n\t\tColor3.new(1, 1, 1),\n\t\t{ Transparency = 1 }\n\t)\n\tMakeLabel(tag, result[1] .. \" = \" .. result[2])\n\tprint(string.format(\"%-7s %s  (%d)\", result[1], ToBinary(result[2]), result[2]))\nend","runtime":""},
"bw-shift":{"k":"S","what":"Packs two grid coordinates into one dictionary key with lshift/bor and unpacks them with rshift/band, then uses it as a key.","services":[],"variables":"","functions":"local function PackKey(x, z)\n\treturn bit32.bor(bit32.lshift(x, 16), z)\nend\n\nlocal function UnpackKey(key)\n\treturn bit32.rshift(key, 16), bit32.band(key, 0xFFFF)\nend","setup":"local blocks = {}\n\nfor x = 1, 5 do\n\tfor z = 1, 5 do\n\t\tlocal key = PackKey(x, z)\n\t\tblocks[key] = MakePart(\n\t\t\tVector3.new(1.8, 0.5, 1.8),\n\t\t\tORIGIN + Vector3.new(x * 2 - 6, 0.25, z * 2 - 6),\n\t\t\tColor3.fromHSV((x + z) / 12, 0.5, 0.9)\n\t\t)\n\tend\nend\n\nlocal key = PackKey(3, 4)\nprint(\"packed (3, 4) ->\", key, \"->\", UnpackKey(key))\nblocks[key].Color = Color3.fromRGB(226, 133, 26)\nMakeLabel(blocks[key], \"key \" .. key .. \" = (3, 4)\")","runtime":""},
"bw-pack":{"k":"S","what":"A lamp's colour is stored as one packed 24-bit number (R << 16 | G << 8 | B) and unpacked with bit32.extract every frame.","services":[],"variables":"","functions":"","setup":"local lamp = MakePart(\n\tVector3.new(4, 4, 4),\n\tORIGIN + Vector3.new(0, 2, 0),\n\tColor3.new(1, 1, 1),\n\t{ Material = Enum.Material.Neon }\n)\n\nlocal label = MakeLabel(lamp)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal red = math.floor(127 + 127 * math.sin(now))\n\tlocal green = math.floor(127 + 127 * math.sin(now * 1.3 + 2))\n\tlocal blue = math.floor(127 + 127 * math.sin(now * 0.7 + 4))\n\tlocal packed = bit32.bor(bit32.lshift(red, 16), bit32.lshift(green, 8), blue)\n\tlamp.Color =\n\t\tColor3.fromRGB(bit32.extract(packed, 16, 8), bit32.extract(packed, 8, 8), bit32.extract(packed, 0, 8))\n\tlabel.Text = string.format(\"packed %d = #%06X\", packed, packed)\nend)"},
"bw-slots":{"k":"S","what":"Sixteen inventory slots as bits. Click to take the first free slot (found with bit32.countrz of the free bits), right-click to empty a random one.","services":[],"variables":"","functions":"","setup":"local usedBits = 0\nlocal slots = {}\n\nfor i = 0, 15 do\n\tslots[i] = MakePart(\n\t\tVector3.new(1.6, 1.6, 1.6),\n\t\tORIGIN + Vector3.new((i - 7.5) * 2, 1, 0),\n\t\tColor3.fromRGB(70, 70, 80)\n\t)\nend\n\nlocal button = MakePart(Vector3.new(3, 1, 3), ORIGIN + Vector3.new(0, 0.5, 5), Color3.fromRGB(226, 133, 26))\nlocal label = MakeLabel(button, \"click: take a slot / right-click: free one\")\nlocal clickDetector = Instance.new(\"ClickDetector\")\nclickDetector.Parent = button\n\nlocal function Redraw()\n\tfor i = 0, 15 do\n\t\tslots[i].Color = bit32.btest(usedBits, bit32.lshift(1, i)) and Color3.fromRGB(226, 133, 26)\n\t\t\tor Color3.fromRGB(70, 70, 80)\n\tend\nend\n\nlocal function FirstFree()\n\tlocal freeBits = bit32.band(bit32.bnot(usedBits), 0xFFFF)\n\tif freeBits == 0 then return nil end\n\treturn bit32.countrz(freeBits)\nend","runtime":"clickDetector.MouseClick:Connect(function()\n\tlocal slot = FirstFree()\n\tif slot then usedBits = bit32.bor(usedBits, bit32.lshift(1, slot)) end\n\tlabel.Text = slot and (\"took slot \" .. slot) or \"inventory full\"\n\tRedraw()\nend)\n\nclickDetector.RightMouseClick:Connect(function()\n\tusedBits = bit32.band(usedBits, bit32.bnot(bit32.lshift(1, math.random(0, 15))))\n\tRedraw()\nend)"},
"bw-autotile":{"k":"S","what":"Builds a road network where each tile picks its shape from a 4-bit neighbour mask (N=1, E=2, S=4, W=8).","services":[],"variables":"local _cell = 4","functions":"","setup":"local MAP = {\n\t\"..........\",\n\t\".########.\",\n\t\".#......#.\",\n\t\".#..#####.\",\n\t\".#..#..#..\",\n\t\".####..#..\",\n\t\"....#..#..\",\n\t\"....####..\",\n}\n\nlocal function IsRoad(x, z)\n\treturn MAP[z] and MAP[z]:sub(x, x) == \"#\"\nend\n\nfor z = 1, #MAP do\n\tfor x = 1, #MAP[1] do\n\t\tif IsRoad(x, z) then\n\t\t\tlocal mask = 0\n\t\t\tif IsRoad(x, z - 1) then mask = bit32.bor(mask, 1) end\n\t\t\tif IsRoad(x + 1, z) then mask = bit32.bor(mask, 2) end\n\t\t\tif IsRoad(x, z + 1) then mask = bit32.bor(mask, 4) end\n\t\t\tif IsRoad(x - 1, z) then mask = bit32.bor(mask, 8) end\n\t\t\tlocal center = ORIGIN + Vector3.new(x * _cell - 20, 0.2, z * _cell - 16)\n\t\t\tlocal hub = MakePart(Vector3.new(2, 0.4, 2), center, Color3.fromRGB(60, 60, 65))\n\t\t\tMakeLabel(hub, tostring(mask))\n\t\t\tfor _, arm in\n\t\t\t\t{\n\t\t\t\t\t{ 1, Vector3.new(0, 0, -1) },\n\t\t\t\t\t{ 2, Vector3.new(1, 0, 0) },\n\t\t\t\t\t{ 4, Vector3.new(0, 0, 1) },\n\t\t\t\t\t{ 8, Vector3.new(-1, 0, 0) },\n\t\t\t\t}\n\t\t\tdo\n\t\t\t\tif bit32.btest(mask, arm[1]) then\n\t\t\t\t\tlocal size = arm[2].X ~= 0 and Vector3.new(1, 0.4, 2) or Vector3.new(2, 0.4, 1)\n\t\t\t\t\tMakePart(size, center + arm[2] * 1.5, Color3.fromRGB(60, 60, 65))\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend","runtime":""},
"bw-layers":{"k":"S","what":"Defines collision layers and \"can hit\" masks, prints who can hit whom, and colours a 4 × 4 grid of blocks by the result.","services":[],"variables":"","functions":"","setup":"local LAYER = { Players = 1, Enemies = 2, PlayerShots = 4, EnemyShots = 8 }\nlocal NAMES = { \"Players\", \"Enemies\", \"PlayerShots\", \"EnemyShots\" }\nlocal MASKS = { Players = 2 + 8, Enemies = 1 + 2 + 4, PlayerShots = 2, EnemyShots = 1 }\n\nlocal function CanHit(attacker, target)\n\treturn bit32.btest(MASKS[attacker], LAYER[target])\nend\n\nfor row, attacker in NAMES do\n\tfor column, target in NAMES do\n\t\tlocal canHitTarget = CanHit(attacker, target)\n\t\tMakePart(\n\t\t\tVector3.new(2, canHitTarget and 2 or 0.4, 2),\n\t\t\tORIGIN + Vector3.new(column * 2.5 - 6, 1, row * 2.5 - 6),\n\t\t\tcanHitTarget and Color3.fromRGB(226, 133, 26) or Color3.fromRGB(70, 70, 80)\n\t\t)\n\t\tif canHitTarget then print(attacker, \"can hit\", target) end\n\tend\nend","runtime":""},
"bw-signed":{"k":"S","what":"Prints how bit32 turns negative numbers into big unsigned ones (two's complement) and how to convert them back.","services":[],"variables":"","functions":"local function ToSigned(unsigned)\n\tif unsigned >= 2 ^ 31 then return unsigned - 2 ^ 32 end\n\treturn unsigned\nend","setup":"for _, number in { -1, -6, -128, 5, 300 } do\n\tlocal unsigned = bit32.band(number, 0xFFFFFFFF)\n\tprint(\n\t\tstring.format(\n\t\t\t\"%5d -> unsigned %10d -> back to %5d   lowest 8 bits %3d\",\n\t\t\tnumber,\n\t\t\tunsigned,\n\t\t\tToSigned(unsigned),\n\t\t\tbit32.band(number, 0xFF)\n\t\t)\n\t)\nend\n\nprint(\"bit32.bnot(5) =\", bit32.bnot(5), \"which is\", ToSigned(bit32.bnot(5)))\nlocal sign = MakePart(Vector3.new(1, 1, 1), ORIGIN + Vector3.new(0, 3, 0), Color3.new(1, 1, 1))\nMakeLabel(sign, \"see the Output window\")","runtime":""},
"bw-morton":{"k":"S","what":"Lights an 8 × 8 grid of tiles in Morton (Z-order) key order, so you can watch the zig-zag Z pattern.","services":[],"variables":"","functions":"local function SpreadBits(number)\n\tnumber = bit32.band(number, 0xFF)\n\tnumber = bit32.band(bit32.bor(number, bit32.lshift(number, 4)), 0x0F0F)\n\tnumber = bit32.band(bit32.bor(number, bit32.lshift(number, 2)), 0x3333)\n\tnumber = bit32.band(bit32.bor(number, bit32.lshift(number, 1)), 0x5555)\n\treturn number\nend\n\nlocal function MortonKey(x, z)\n\treturn bit32.bor(SpreadBits(x), bit32.lshift(SpreadBits(z), 1))\nend","setup":"local tiles = {}\n\nfor x = 0, 7 do\n\tfor z = 0, 7 do\n\t\ttiles[MortonKey(x, z)] = MakePart(\n\t\t\tVector3.new(1.8, 0.4, 1.8),\n\t\t\tORIGIN + Vector3.new(x * 2 - 7, 0.2, z * 2 - 7),\n\t\t\tColor3.fromRGB(70, 70, 80)\n\t\t)\n\tend\nend","runtime":"while true do\n\tfor key = 0, 63 do\n\t\ttiles[key].Color = Color3.fromHSV(key / 64, 0.7, 1)\n\t\ttask.wait(0.08)\n\tend\n\ttask.wait(1)\n\tfor key = 0, 63 do\n\t\ttiles[key].Color = Color3.fromRGB(70, 70, 80)\n\tend\nend"}
});
})();
